#include <stdio.h>
#include <stdlib.h>

#define MOD 1000000007LL

static long long mod_pow(long long a, long long e) {
    long long r = 1 % MOD;
    while (e > 0) {
        if (e & 1) r = (r * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }
    return r;
}

int main(void) {
    long long N, K;
    if (scanf("%lld %lld", &N, &K) != 2) return 0;

    if (K < 1 || K > N) {
        printf("0\n");
        return 0;
    }

    if (N == 1) {
        printf("%d\n", K == 1 ? 1 : 0);
        return 0;
    }

    /* 
       Let the final deque after insertion be:
       [a_m, ..., a_1, 1, b_1, ..., b_t]
       where {a_i} and {b_i} partition {2,...,N}, and cards inserted to the front
       appear on the left in reverse insertion order.

       During eating, at each step we remove from either end, so the produced sequence
       is any interleaving of:
         a_m, a_{m-1}, ..., a_1, 1, b_1, ..., b_t
       obtained by repeatedly taking leftmost or rightmost remaining card.

       For card 1 to be eaten at position K, exactly K-1 cards must be eaten before it.
       Since 1 blocks left and right sides, before eating 1 we must have eaten all cards
       from one side prefix-completely:
         choose x cards from the left side and y cards from the right side with x+y=K-1,
         and this is possible iff x = m or y = t.
       Counting over all possible final deques is equivalent to choosing for each card 2..N
       whether it is on the left or right of 1.

       Thus valid partitions are those with:
         m <= K-1 and t <= K-1
       because if both m,t >= K, then after K-1 removals 1 is still not exposed.
       Since m+t=N-1, this means:
         max(0, N-K) <= m <= K-1

       For each choice of m cards placed on the left, the final deque is uniquely determined.
       Hence answer = sum_{m=max(0,N-K)}^{K-1} C(N-1,m).

       Using symmetry and a standard identity:
         sum_{m=L}^{R} C(N-1,m)
       We compute directly with factorials.
    */

    long long M = N - 1;

    long long L = N - K;
    if (L < 0) L = 0;
    long long R = K - 1;
    if (R > M) R = M;

    if (L > R) {
        printf("0\n");
        return 0;
    }

    long long *fact = (long long *)malloc((M + 1) * sizeof(long long));
    long long *invfact = (long long *)malloc((M + 1) * sizeof(long long));
    if (!fact || !invfact) return 0;

    fact[0] = 1;
    for (long long i = 1; i <= M; i++) fact[i] = fact[i - 1] * i % MOD;

    invfact[M] = mod_pow(fact[M], MOD - 2);
    for (long long i = M; i >= 1; i--) invfact[i - 1] = invfact[i] * i % MOD;

    long long ans = 0;
    for (long long m = L; m <= R; m++) {
        long long comb = fact[M] * invfact[m] % MOD * invfact[M - m] % MOD;
        ans += comb;
        if (ans >= MOD) ans -= MOD;
    }

    printf("%lld\n", ans);

    free(fact);
    free(invfact);
    return 0;
}

