import java.util.Scanner;

public class Main {
    static final int MOD = 1_000_000_007;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int K = sc.nextInt();
        sc.close();

        // Precompute factorials
        long[] fact = new long[N + 1];
        long[] invFact = new long[N + 1];
        fact[0] = 1;
        for (int i = 1; i <= N; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        invFact[N] = modPow(fact[N], MOD - 2);
        for (int i = N - 1; i >= 0; i--) {
            invFact[i] = invFact[i + 1] * (i + 1) % MOD;
        }

        long answer = 0;
        for (int a = 0; a <= N - 1; a++) {
            int b = N - 1 - a;
            int minL = Math.max(0, K - 1 - b);
            int maxL = Math.min(a, K - 1);
            if (minL > maxL) continue;
            long sumL = 0;
            for (int L = minL; L <= maxL; L++) {
                sumL = (sumL + nCr(K - 1, L, fact, invFact)) % MOD;
            }
            long ways = nCr(N - 1, a, fact, invFact);
            answer = (answer + ways * sumL) % MOD;
        }

        System.out.println(answer);
    }

    static long nCr(int n, int r, long[] fact, long[] invFact) {
        if (r < 0 || r > n) return 0;
        return fact[n] * invFact[r] % MOD * invFact[n - r] % MOD;
    }

    static long modPow(long a, long e) {
        long res = 1;
        while (e > 0) {
            if ((e & 1) == 1) res = res * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return res;
    }
}

