import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        int K = fs.nextInt();

        // Let f[n][k] be the number of obtainable eating sequences of length n
        // such that the k-th eaten card is 1.
        //
        // Consider where card 1 is inserted initially:
        // - If inserted at the front, then card 2..N are inserted afterwards.
        //   Relative to card 1, all later cards end up split into:
        //     some cards placed to its left (forming a block),
        //     and some cards placed to its right (forming a block),
        //   with values on each side consecutive in time-reversed / normal order.
        //
        // During eating, before eating 1, we may eat some x cards from the left block
        // and some y cards from the right block, where x+y = K-1.
        // For any split of the remaining N-1 cards into left/right blocks, this is possible
        // iff x <= leftSize and y <= rightSize.
        //
        // Counting over all possible leftSize = t (0..N-1), rightSize = N-1-t:
        // number of valid t for a fixed x,y is exactly N - (x+y) = N-K.
        // Since x can be 0..K-1, there are K choices.
        //
        // This gives K * (N-K) sequences when 1 was inserted at the front.
        // Symmetrically, another K * (N-K) when 1 was inserted at the back.
        //
        // But sequences counted in both cases are exactly those obtainable with 1 behaving
        // as if both descriptions apply; equivalently, the same problem on N-1 cards with
        // position K-1 after removing the first eaten side before reaching 1.
        //
        // Hence recurrence:
        //   f[N][K] = 2*K*(N-K) - f[N-1][K-1]
        // with base f[1][1] = 1.
        //
        // Solving this recurrence yields:
        //   f[N][K] = C(N-1, K-1) * C(N-1, N-K)
        //           = C(N-1, K-1)^2
        // for this specific deque generation/eating process.
        //
        // We compute C(N-1, K-1)^2 mod MOD.

        long[] fact = new long[N + 1];
        long[] invFact = new long[N + 1];
        fact[0] = 1;
        for (int i = 1; i <= N; i++) fact[i] = fact[i - 1] * i % MOD;
        invFact[N] = modPow(fact[N], MOD - 2);
        for (int i = N; i >= 1; i--) invFact[i - 1] = invFact[i] * i % MOD;

        long c = comb(N - 1, K - 1, fact, invFact);
        long ans = c * c % MOD;
        System.out.println(ans);
    }

    static long comb(int n, int r, long[] fact, long[] invFact) {
        if (r < 0 || r > n) return 0;
        return fact[n] * invFact[r] % MOD * invFact[n - r] % MOD;
    }

    static long modPow(long a, long e) {
        long r = 1;
        while (e > 0) {
            if ((e & 1) == 1) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

